const studioSetOptions=(el,items)=>{el.replaceChildren();[...new Set(items||[])].forEach((v,i)=>{const o=document.createElement('option');o.value=String(v);o.textContent=String(v);if(i===0)o.selected=true;el.appendChild(o);});};
function studioRefreshThemeBrief(){
 const theme=studioTheme.value,category=studioCategory.value,specific=studioSpecific.value;
 if(!theme||!category||!specific||typeof window.trozalBuildThemeCreativeBrief!=='function')return null;
 const brief=window.trozalBuildThemeCreativeBrief(theme,category,specific);
 const details=$('trozalJsDetails').value.trim();
 $('trozalJsThemeBrief').textContent=brief.summary+'\n\nSPESIFIKASI LENGKAP:\n'+brief.prompt+'\n\nDETAIL TAMBAHAN:\n'+(details||'Belum ada detail tambahan.')+'\n\nATURAN: Detail tambahan bersifat aditif. Jangan menghapus tujuan tema, subjek, aset, palet, komposisi, urutan gerak, atau batasan domain.';
 return brief;
}
function studioApplyTheme(theme){
 const name=String(theme||'').trim();if(!name)return;
 if(![...studioTheme.options].some(o=>o.value===name)){const o=document.createElement('option');o.value=name;o.textContent=name;studioTheme.appendChild(o);}
 studioTheme.value=name;studioSearch.value=name;
 const profile=typeof window.trozalThemeProfile==='function'?window.trozalThemeProfile(name):null;
 const domain=typeof window.trozalGetThemeDomainProfile==='function'?window.trozalGetThemeDomainProfile(name):null;
 studioSetOptions(studioCategory,[...(profile?.styles||[]),...(domain?.styles||[])]);
 studioSetOptions(studioSpecific,[...(profile?.specifics||[]),...(domain?.subthemes||[]).map(x=>name+' — '+x)]);
 studioRefreshThemeBrief();
}
function studioRenderThemeSearch(){
 const q=studioSearch.value.trim().toLowerCase();studioResults.replaceChildren();
 if(!q){studioResults.hidden=true;return;}
 const matches=studioThemeNames.filter(x=>x.toLowerCase().includes(q)).slice(0,18);
 matches.forEach(name=>{const b=document.createElement('button');b.type='button';b.textContent=name;b.addEventListener('click',()=>{studioApplyTheme(name);studioResults.hidden=true;});studioResults.appendChild(b);});
 studioResults.hidden=!matches.length;
}
studioSetOptions(studioTheme,studioThemeNames);
