studioCategory.addEventListener('change',studioRefreshThemeBrief);
studioSpecific.addEventListener('change',studioRefreshThemeBrief);
$('trozalJsDetails').addEventListener('input',studioRefreshThemeBrief);
studioSearch.addEventListener('input',studioRenderThemeSearch);
studioSearch.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const first=studioResults.querySelector('button');if(first)first.click();else if(studioSearch.value.trim())studioApplyTheme(studioSearch.value.trim());}});
$('trozalJsThemeRandom').addEventListener('click',()=>{if(!studioThemeNames.length)return;const current=studioTheme.value;const choices=studioThemeNames.filter(x=>x!==current);studioApplyTheme(choices[Math.floor(Math.random()*choices.length)]);});
