function studioBuildFullPrompt(){
 const theme=studioTheme.value,category=studioCategory.value,specific=studioSpecific.value;
 const brief=window.trozalBuildThemeCreativeBrief?.(theme,category,specific);
 if(!brief?.prompt)throw new Error('Mesin spesifikasi tema Professional Mode belum siap.');
 const detail=$('trozalJsDetails').value.trim(),free=$('trozalJsAiPrompt').value.trim();
 const ratio=$('trozalJsPromptRatio').value,duration=$('trozalJsPromptDuration').value,resolution=Number($('trozalJsPromptResolution').value)||2160;
 let width=resolution,height=Math.round(resolution*9/16);
 if(ratio.startsWith('9:16')){width=Math.round(resolution*9/16);height=resolution;}else if(ratio.startsWith('1:1')){width=height=resolution;}else if(ratio.startsWith('4:5')){width=Math.round(resolution*4/5);height=resolution;}
 const count=Math.max(1,Math.min(4,Number($('trozalJsAiCount').value)||3));
 const prompt=[
 'ROLE: You are a senior motion-graphics art director and production Canvas 2D JavaScript creative coder.',
 'MAIN THEME: '+theme,
 'VISUAL CATEGORY: '+category,
 'SPECIFIC CATEGORY / SUBTHEME: '+specific,
 'THEME-SPECIFIC CREATIVE BLUEPRINT (preserve every instruction):',
 brief.prompt,
 'ADDITIONAL USER DETAILS (additive, never replace the automatic specification): '+(detail||'No extra detail supplied.'),
 'FREEFORM USER BRIEF (preserve all requirements): '+(free||'Use the selected theme and complete creative specification as the brief.'),
 'CREATIVE DIRECTION:',
 'Palette: '+$('trozalJsPalette').value,
 'Camera: '+$('trozalJsCamera').value,
 'Transition: '+$('trozalJsTransition').value,
 'Typography: '+$('trozalJsTypography').value,
 'Motion choreography: '+$('trozalJsMotionPreset').value,
 'Motion tempo: '+$('trozalJsMotionTempo').value,
 'Motion intensity: '+$('trozalJsMotionIntensity').value,
 'DELIVERY: Generate exactly '+count+' distinct complete Canvas 2D JavaScript motion concepts.',
 'TARGET VIDEO: '+duration+', aspect ratio '+ratio+', canvas '+width+' × '+height+' pixels.',
 'CODE CONTRACT: Each concept must be a self-contained JavaScript function body executed as (ctx,t,w,h,anim). Use Canvas 2D only; t is seconds. Draw the complete frame including background. Use deterministic animation, coherent scene choreography, readable typography drawn with Canvas, deliberate easing, depth, lighting, and a strong ending/hold.',
 'OUTPUT FORMAT: Return ONLY valid JSON: {"concepts":[{"title":"...","description":"...","code":"..."}]}. Each code field contains runnable JavaScript source only. No Markdown fences or prose outside JSON.',
 'SAFETY / RUNTIME: No HTML, DOM, window, document, network, fetch, storage, timers, workers, external assets, imports, eval, or Function constructors. Use ctx and standard deterministic math only. Keep each code under 12000 characters.',
 'QUALITY: Do not reduce the brief to generic floating circles. Use the theme-specific assets, objects, visual vocabulary, domain exclusions, category grammar, palette, composition, and motion sequence. Additional details are additive.'
 ].join('\n\n');
 $('trozalJsAiFullPrompt').value=prompt;
 $('trozalJsAiStatus').textContent='Prompt lengkap dibuat · '+theme+' · '+category+' · '+count+' konsep · '+duration+'.';
 return prompt;
}
